/**
 * This test writes {@link #NUM_STRINGS} using {@link VarByteChunkSingleValueWriter}. It then reads
 * the strings using {@link VarByteChunkSingleValueReader}, and asserts that what was written is the same as
 * what was read in.
 *
 * Number of docs and docs per chunk are chosen to generate complete as well partial chunks.
 *
 * @throws Exception
 */
@Test
public void test() throws Exception {
    String[] expected = new String[NUM_STRINGS];
    Random random = new Random();
    File outFile = new File(TEST_FILE);
    FileUtils.deleteQuietly(outFile);
    int maxStringLengthInBytes = 0;
    for (int i = 0; i < NUM_STRINGS; i++) {
        expected[i] = RandomStringUtils.random(random.nextInt(MAX_STRING_LENGTH));
        maxStringLengthInBytes = Math.max(maxStringLengthInBytes, expected[i].getBytes(UTF_8).length);
    }
    ChunkCompressor compressor = ChunkCompressorFactory.getCompressor("snappy");
    VarByteChunkSingleValueWriter writer = new VarByteChunkSingleValueWriter(outFile, compressor, NUM_STRINGS, NUM_DOCS_PER_CHUNK, maxStringLengthInBytes);
    for (int i = 0; i < NUM_STRINGS; i++) {
        writer.setString(i, expected[i]);
    }
    writer.close();
    PinotDataBuffer pinotDataBuffer = PinotDataBuffer.fromFile(outFile, ReadMode.mmap, FileChannel.MapMode.READ_ONLY, getClass().getName());
    ChunkDecompressor uncompressor = ChunkCompressorFactory.getDecompressor("snappy");
    VarByteChunkSingleValueReader reader = new VarByteChunkSingleValueReader(pinotDataBuffer, uncompressor);
    ChunkReaderContext context = reader.createContext();
    for (int i = 0; i < NUM_STRINGS; i++) {
        String actual = reader.getString(i, context);
        Assert.assertEquals(actual, expected[i]);
    }
    reader.close();
    FileUtils.deleteQuietly(outFile);
}

@Test
public void testSingleColMultiValue() throws Exception {
    int maxBits = 2;
    while (maxBits < 32) {
        LOGGER.debug("START test maxBit:" + maxBits);
        File file = new File("test_single_col_multi_value_writer.dat");
        file.delete();
        int rows = 100;
        int[][] data = new int[rows][];
        int maxValue = (int) Math.pow(2, maxBits);
        Random r = new Random();
        int totalNumValues = 0;
        for (int i = 0; i < rows; i++) {
            int numValues = r.nextInt(100) + 1;
            data[i] = new int[numValues];
            for (int j = 0; j < numValues; j++) {
                data[i][j] = r.nextInt(maxValue);
            }
            totalNumValues += numValues;
        }
        FixedBitMultiValueWriter writer = new FixedBitMultiValueWriter(file, rows, totalNumValues, maxBits);
        CustomBitSet bitSet = CustomBitSet.withBitLength(totalNumValues * maxBits);
        int numChunks = writer.getNumChunks();
        int[] chunkOffsets = new int[numChunks];
        int chunkId = 0;
        int offset = 0;
        int index = 0;
        for (int i = 0; i < rows; i++) {
            writer.setIntArray(i, data[i]);
            if (i % writer.getRowsPerChunk() == 0) {
                chunkOffsets[chunkId] = offset;
                chunkId = chunkId + 1;
            }
            offset += data[i].length;
            for (int j = 0; j < data[i].length; j++) {
                int value = data[i][j];
                for (int bitPos = maxBits - 1; bitPos >= 0; bitPos--) {
                    if ((value & (1 << bitPos)) != 0) {
                        bitSet.setBit(index * maxBits + (maxBits - bitPos - 1));
                    }
                }
                index = index + 1;
            }
        }
        writer.close();
        LOGGER.trace("chunkOffsets: {}", Arrays.toString(chunkOffsets));
        //start validating the file
        RandomAccessFile raf = new RandomAccessFile(file, "r");
        Assert.assertEquals(raf.length(), writer.getTotalSize());
        DataInputStream dis = new DataInputStream(new FileInputStream(file));
        for (int i = 0; i < numChunks; i++) {
            Assert.assertEquals(dis.readInt(), chunkOffsets[i]);
        }
        int numBytesForBitmap = (totalNumValues + 7) / 8;
        Assert.assertEquals(writer.getBitsetSize(), numBytesForBitmap);
        byte[] bitsetBytes = new byte[numBytesForBitmap];
        dis.read(bitsetBytes);
        CustomBitSet customBit = CustomBitSet.withByteBuffer(numBytesForBitmap, ByteBuffer.wrap(bitsetBytes));
        offset = 0;
        LOGGER.trace(customBit.toString());
        for (int i = 0; i < rows; i++) {
            Assert.assertTrue(customBit.isBitSet(offset));
            offset += data[i].length;
        }
        byte[] byteArray = bitSet.toByteArray();
        LOGGER.trace("raf.length():" + raf.length());
        LOGGER.trace("getTotalSize:" + writer.getTotalSize());
        LOGGER.trace("getRawDataSize:" + writer.getRawDataSize());
        LOGGER.trace("getBitsetSize:" + writer.getBitsetSize());
        LOGGER.trace("getChunkOffsetHeaderSize:" + writer.getChunkOffsetHeaderSize());
        int dataLength = (int) (writer.getTotalSize() - writer.getChunkOffsetHeaderSize() - numBytesForBitmap);
        byte[] rawData = new byte[dataLength];
        // read the data segment that starts after the header.
        dis.read(rawData);
        Assert.assertEquals(rawData.length, byteArray.length);
        Assert.assertEquals(rawData, byteArray);
        raf.close();
        dis.close();
        file.delete();
        LOGGER.debug("END test maxBit:" + maxBits);
        maxBits = maxBits + 1;
        bitSet.close();
        customBit.close();
    }
}

@Test
public void testSingleColUnsigned() throws Exception {
    int maxBits = 1;
    while (maxBits < 32) {
        LOGGER.debug("START test maxBits:" + maxBits);
        final String fileName = getClass().getName() + "_single_col_fixed_bit_" + maxBits + ".dat";
        final File file = new File(fileName);
        file.delete();
        final int rows = 100;
        final int cols = 1;
        final int[] columnSizesInBits = new int[] { maxBits };
        final FixedBitSingleValueMultiColWriter writer = new FixedBitSingleValueMultiColWriter(file, rows, cols, columnSizesInBits);
        final int[] data = new int[rows];
        final Random r = new Random();
        writer.open();
        final int maxValue = (int) Math.pow(2, maxBits);
        final CustomBitSet set = CustomBitSet.withBitLength(rows * cols * maxBits);
        for (int i = 0; i < rows; i++) {
            data[i] = r.nextInt(maxValue);
            writer.setInt(i, 0, data[i]);
            final int value = data[i];
            for (int bitPos = maxBits - 1; bitPos >= 0; bitPos--) {
                if ((value & (1 << bitPos)) != 0) {
                    set.setBit(i * maxBits + (maxBits - bitPos - 1));
                }
            }
        }
        LOGGER.debug("bits expected:" + rows * cols * maxBits + " bytes expected:" + (rows * cols * maxBits + 7) / 8);
        writer.close();
        final RandomAccessFile raf = new RandomAccessFile(file, "r");
        //      System.out.println("file size:" + raf.length());
        final byte[] b = new byte[(int) raf.length()];
        raf.read(b);
        final byte[] byteArray = set.toByteArray();
        if (byteArray.length != raf.length()) {
            final byte[] temp = set.toByteArray();
            System.err.println("byteArray length:" + temp.length + "   from file:" + b.length);
        }
        LOGGER.trace("byteArray length:" + byteArray.length + "   from file:" + b.length);
        Assert.assertEquals(byteArray.length, b.length);
        Assert.assertEquals(byteArray, b);
        raf.close();
        LOGGER.trace("END test maxBits:" + maxBits);
        maxBits = maxBits + 1;
        file.delete();
        set.close();
    }
}

@Test
public void testSingleColSigned() throws Exception {
    int maxBits = 1;
    while (maxBits < 32) {
        LOGGER.trace("START test maxBits:" + maxBits);
        final String fileName = getClass().getName() + "_single_col_fixed_bit_" + maxBits + ".dat";
        final File file = new File(fileName);
        file.delete();
        final int rows = 100;
        final int cols = 1;
        final int[] columnSizesInBits = new int[] { maxBits };
        final FixedBitSingleValueMultiColWriter writer = new FixedBitSingleValueMultiColWriter(file, rows, cols, columnSizesInBits, new boolean[] { true });
        final int[] data = new int[rows];
        final Random r = new Random();
        writer.open();
        final int maxValue = (int) Math.pow(2, maxBits);
        int offset = maxValue - 1;
        int requiredBits = maxBits + 1;
        final CustomBitSet set = CustomBitSet.withBitLength(rows * cols * requiredBits);
        for (int i = 0; i < rows; i++) {
            int value = r.nextInt(maxValue);
            if (Math.random() > .5) {
                value = -1 * value;
            }
            data[i] = value;
            writer.setInt(i, 0, data[i]);
            int offsetValue = value + offset;
            for (int bitPos = requiredBits - 1; bitPos >= 0; bitPos--) {
                if ((offsetValue & (1 << bitPos)) != 0) {
                    set.setBit(i * requiredBits + (requiredBits - bitPos - 1));
                }
            }
        }
        LOGGER.trace("bits expected:" + rows * cols * maxBits + " bytes expected:" + (rows * cols * maxBits + 7) / 8);
        writer.close();
        final RandomAccessFile raf = new RandomAccessFile(file, "r");
        LOGGER.trace("file size:" + raf.length());
        final byte[] b = new byte[(int) raf.length()];
        raf.read(b);
        final byte[] byteArray = set.toByteArray();
        if (byteArray.length != raf.length()) {
            final byte[] temp = set.toByteArray();
            System.err.println("byteArray length:" + temp.length + "   from file:" + b.length);
        }
        LOGGER.trace("byteArray length:" + byteArray.length + "   from file:" + b.length);
        Assert.assertEquals(byteArray.length, b.length);
        Assert.assertEquals(byteArray, b);
        raf.close();
        LOGGER.trace("END test maxBits:" + maxBits);
        maxBits = maxBits + 1;
        file.delete();
        set.close();
    }
}

@Test
public void testSingleColMultiValue() throws Exception {
    int maxBits = 2;
    while (maxBits < 32) {
        LOGGER.trace("START test maxBit:" + maxBits);
        File file = new File("test_single_col_multi_value_writer.dat");
        file.delete();
        int rows = 100;
        int[][] data = new int[rows][];
        int maxValue = (int) Math.pow(2, maxBits);
        Random r = new Random();
        int totalNumValues = 0;
        for (int i = 0; i < rows; i++) {
            int numValues = r.nextInt(100) + 1;
            data[i] = new int[numValues];
            for (int j = 0; j < numValues; j++) {
                data[i][j] = r.nextInt(maxValue);
            }
            totalNumValues += numValues;
        }
        FixedBitSingleColumnMultiValueWriter writer = new FixedBitSingleColumnMultiValueWriter(file, rows, totalNumValues, maxBits);
        CustomBitSet bitSet = CustomBitSet.withBitLength(totalNumValues * maxBits);
        int index = 0;
        for (int i = 0; i < rows; i++) {
            writer.setIntArray(i, data[i]);
            for (int j = 0; j < data[i].length; j++) {
                int value = data[i][j];
                for (int bitPos = maxBits - 1; bitPos >= 0; bitPos--) {
                    if ((value & (1 << bitPos)) != 0) {
                        bitSet.setBit(index * maxBits + (maxBits - bitPos - 1));
                    }
                }
                index = index + 1;
            }
        }
        writer.close();
        // verify header
        DataInputStream dis = new DataInputStream(new FileInputStream(file));
        int totalLength = 0;
        for (int i = 0; i < rows; i++) {
            Assert.assertEquals(dis.readInt(), totalLength);
            Assert.assertEquals(dis.readInt(), data[i].length);
            totalLength += data[i].length;
        }
        dis.close();
        // verify data
        byte[] byteArray = bitSet.toByteArray();
        RandomAccessFile raf = new RandomAccessFile(file, "r");
        // Header contains 1 row for each doc and each row contains 2 ints
        int headerSize = rows * 2 * 4;
        int dataLength = (int) raf.length() - headerSize;
        byte[] b = new byte[dataLength];
        // read the data segment that starts after the header.
        raf.seek(headerSize);
        raf.read(b, 0, dataLength);
        Assert.assertEquals(byteArray.length, b.length);
        Assert.assertEquals(byteArray, b);
        raf.close();
        file.delete();
        LOGGER.trace("END test maxBit:" + maxBits);
        maxBits = maxBits + 1;
        bitSet.close();
    }
}

