@Test
public void test() {
    // No alwaysFalse predicates
    testQuery(String.format("select count(*) from %s where (%s = 'dim_0_1' AND %s <> 'dim_1_2')", TABLE_NAME, DIMENSIONS[0], DIMENSIONS[1]));
    // (nonAlwaysFalse AND (nonAlwaysFalse AND alwaysFalse)
    testQuery(String.format("select count(*) from %s where (%s = 'dim_0_1' AND (%s <> 'dim_1_2' AND %s = 'x'))", TABLE_NAME, DIMENSIONS[0], DIMENSIONS[1], DIMENSIONS[2]));
    // (alwaysFalse OR (alwaysFalse OR alwaysFalse))
    testQuery(String.format("select count(*) from %s where (%s = 'x' OR (%s ='y' OR %s = 'z'))", TABLE_NAME, DIMENSIONS[0], DIMENSIONS[1], DIMENSIONS[2]));
    // ((alwaysFalse AND nonAlwaysFalse) OR AlwaysFalse)
    testQuery(String.format("select count(*) from %s where ((%s = 'x' AND %s ='dim_1_5') OR %s = 'z')", TABLE_NAME, DIMENSIONS[0], DIMENSIONS[1], DIMENSIONS[2]));
}

