@Test
public void testHllOnPregeneratedColumn() throws Exception {
    File destinationDir = null;
    try {
        destinationDir = Files.createTempDirectory(PregeneratedHllTest.class.getName()).toFile();
        final String segmentName = "pregeneratedHllSegment";
        createLoadSegment(segmentName, destinationDir);
        // Init Query Executor
        final List<AvroQueryGenerator.TestSimpleAggreationQuery> aggCalls = new ArrayList<>();
        aggCalls.add(new AvroQueryGenerator.TestSimpleAggreationQuery("select fasthll(column1_hll) from " + testHelper.tableName + " where column1 > 100000 limit 0", 0.0));
        aggCalls.add(new AvroQueryGenerator.TestSimpleAggreationQuery("select distinctcounthll(column1) from " + testHelper.tableName + " where column1 > 100000 limit 0", 0.0));
        // we give high value of 1000 because this test also runs with log2m different from distinctCounthll
        // function. There is no guarantee about counts or accuracy. I want to make sure these are valid values
        ApproximateQueryTestUtil.runApproximationQueries(testHelper.queryExecutor, helper.getSegmentName(), aggCalls, 1000, testHelper.serverMetrics);
        Double val1 = (Double) ApproximateQueryTestUtil.runQuery(testHelper.queryExecutor, Arrays.asList(helper.getSegmentName()), aggCalls.get(0), testHelper.serverMetrics);
        // 5000, because we know
        Assert.assertTrue(val1 > 5000);
        // add one more segment. Goal to verify that combine works correctly
        // across multiple segments. Not interested in exact values
        final String secondSegmentName = "segment2";
        createLoadSegment(secondSegmentName, destinationDir);
        ApproximateQueryTestUtil.runApproximationQueries(testHelper.queryExecutor, Arrays.asList(helper.getSegmentName(), secondSegmentName), aggCalls, 1000, testHelper.serverMetrics);
        Double val2 = (Double) ApproximateQueryTestUtil.runQuery(testHelper.queryExecutor, Arrays.asList(helper.getSegmentName(), secondSegmentName), aggCalls.get(0), testHelper.serverMetrics);
        // both segments are same....distinct count should be same
        Assert.assertEquals(val1, val2);
    } finally {
        FileUtils.deleteQuietly(destinationDir);
    }
}

